  'psychological-testing-and-assessment',
  null,
  'Psychological Testing and Assessment',
  'Psychological Testing and Assessment',
  'Psychological Testing and Assessment introduces the science and practice of psychological measurement. Students learn reliability, validity, test construction, norms, standard scores, fairness, ethics, and applied assessment across cognitive, achievement, personality, clinical, behavioral, neuropsychological, and educational contexts. The course covers psychometrics and applied assessment material to provide a comprehensive syllabus.',
  $psytjson${"slug": "psychological-testing-and-assessment", "title": "Psychological Testing and Assessment", "description": "Psychological Testing and Assessment introduces the science and practice of psychological measurement. Students learn reliability, validity, test construction, norms, standard scores, fairness, ethics, and applied assessment across cognitive, achievement, personality, clinical, behavioral, neuropsychological, and educational contexts. The course covers psychometrics and applied assessment material to provide a comprehensive syllabus.", "topics": [{"id": "43d24693-0fe3-43ab-95fb-6ba20cdd4ee6", "type": "topic", "title": "Foundations of Psychological Testing and Assessment", "description": "Students learn what tests can and cannot do, how assessment differs from casual judgment, and why responsible use depends on evidence and context.", "children": [{"id": "8fbb9d0f-b9b5-48eb-a6a9-08beb0c4d790", "type": "subtopic", "title": "Assessment purposes", "children": [{"id": "77eceb2f-bc8d-4829-8c4f-832c4ac00e66", "type": "concept", "title": "Screening, diagnosis, classification, placement, eligibility, treatment planning, and progress monitoring"}, {"id": "30688b01-742c-4b4c-9875-0dee93219178", "type": "concept", "title": "Research, occupational, educational, forensic, and clinical contexts"}, {"id": "f85fcc9f-736f-4b2b-8a10-534c76dea9ce", "type": "concept", "title": "Benefits, limits, and risks of psychological testing"}], "description": "The point is to understand why assessment is conducted before choosing tools or drawing conclusions."}, {"id": "00283f27-f6d1-4b17-9793-822558eaf86b", "type": "subtopic", "title": "Assessment versus testing", "children": [{"id": "147ae4aa-4e10-4de5-bed1-8aece20bedeb", "type": "concept", "title": "Interviews, observations, records, collateral data, and standardized tests"}, {"id": "1a4521d9-3063-482c-8244-c9660cf0e586", "type": "concept", "title": "Hypothesis testing and multi-method assessment"}, {"id": "96673d99-8501-44cc-8129-95bc38fa41b1", "type": "concept", "title": "Clinical judgment, actuarial tools, and structured decision-making"}], "description": "Students learn that testing is one method inside a broader assessment process."}, {"id": "e3076142-da22-4e0c-9a56-a70851a84fa7", "type": "subtopic", "title": "Professional mindset", "children": [{"id": "0509061f-7c6c-472b-bbf7-4e93376d78dd", "type": "concept", "title": "Evidence-based practice"}, {"id": "329823c7-fb2d-4619-b2e6-064906b03a42", "type": "concept", "title": "Limits of inference and base rates"}, {"id": "a75bf5ec-b0ae-459e-a4a5-476ff14cdc20", "type": "concept", "title": "Impact on examinees, families, institutions, and policy"}], "description": "Responsible assessment requires skepticism, humility, documentation, and awareness of consequences."}]}, {"id": "c5903138-ebd7-42ee-9078-36daa260db7e", "type": "topic", "title": "Measurement Theory, Scales, Norms, and Standard Scores", "description": "This topic builds the vocabulary for turning observations and responses into interpretable psychological scores.", "children": [{"id": "36dec649-af1e-48ab-9321-5ab96b5833ba", "type": "subtopic", "title": "Measurement basics", "children": [{"id": "86f0440c-1126-4c75-94cf-72ce0950c910", "type": "concept", "title": "Constructs, indicators, operational definitions, and observables"}, {"id": "8d188c64-b165-401e-bca8-b1974f78e42d", "type": "concept", "title": "Nominal, ordinal, interval, and ratio scales"}, {"id": "eb58e93a-55ec-464b-85a4-d0ed88c8e03b", "type": "concept", "title": "Raw scores, derived scores, and score transformations"}], "description": "Students learn how psychological constructs become operationalized as scores."}, {"id": "429f64e9-2b5d-4452-aefb-62da6bc6af60", "type": "subtopic", "title": "Norms and standardization", "children": [{"id": "5a25288a-b0cf-493c-ae27-c969ce80b571", "type": "concept", "title": "Norm samples, representativeness, and sampling error"}, {"id": "77e28c65-f658-4a41-8dee-e5c1e2e308c9", "type": "concept", "title": "Percentiles, z-scores, T-scores, stanines, scaled scores, and IQ scores"}, {"id": "5f5dbf6a-f03f-456c-b760-6be1de7967f1", "type": "concept", "title": "Age, grade, local, national, and criterion-referenced norms"}], "description": "Norms let scores be interpreted relative to a defined reference group."}, {"id": "e366dc10-39bb-4309-90b8-ba74fdf3a887", "type": "subtopic", "title": "Score interpretation", "children": [{"id": "c0d3b4ad-0eed-4623-8991-057ebb7e377c", "type": "concept", "title": "Measurement error and confidence intervals"}, {"id": "5938753f-987e-464b-acbd-3e7734668589", "type": "concept", "title": "Base rates, cut scores, and classification"}, {"id": "2935c40e-1ac3-452f-b6df-3528ff5a0284", "type": "concept", "title": "Ipsative, normative, and criterion interpretations"}], "description": "The gist is to avoid treating scores as direct facts about people."}]}, {"id": "b58a894a-16ba-4d8a-8df2-210f2fa560fd", "type": "topic", "title": "Reliability, Error, Precision, and Decision Confidence", "description": "Students learn how much trust to place in scores and decisions by examining consistency, error, and uncertainty.", "children": [{"id": "a2dd9a33-19f4-456f-a839-b2042ee47084", "type": "subtopic", "title": "Reliability types", "children": [{"id": "8d118b04-cf55-4989-aa7e-9ca7e1c60c75", "type": "concept", "title": "Internal consistency and coefficient alpha/omega"}, {"id": "3d2fcc0f-4f3b-4118-827d-92a27689cee5", "type": "concept", "title": "Test-retest, alternate forms, interrater, and scorer reliability"}, {"id": "53ad3263-3d32-43cc-b219-39ce0aac315c", "type": "concept", "title": "Generalizability across items, raters, occasions, and contexts"}], "description": "Students learn different ways tests can be consistent or inconsistent."}, {"id": "d7577ef9-2e69-452b-9b76-10b43e81ce21", "type": "subtopic", "title": "Error and precision", "children": [{"id": "baf3d785-65cd-4ae5-be5a-22d9a83fe242", "type": "concept", "title": "Standard error of measurement"}, {"id": "181938e6-affd-445e-9d53-602f00ede198", "type": "concept", "title": "Confidence intervals and reliable change"}, {"id": "15ff48a2-7cb7-494c-9e94-f00c37f2bd38", "type": "concept", "title": "False positives, false negatives, and decision error"}], "description": "Reliability is translated into practical uncertainty around scores."}, {"id": "f195a316-7504-4ec0-94e3-9aad765948b4", "type": "subtopic", "title": "Improving dependability", "children": [{"id": "adc423af-4a2b-43f8-9513-4145b7a83f93", "type": "concept", "title": "Clear constructs and items"}, {"id": "b26588d8-ce27-4c86-8ecd-75af88090354", "type": "concept", "title": "Standardized instructions and scoring"}, {"id": "aa915e01-933f-4ff5-8fc7-01da4ab579b1", "type": "concept", "title": "Training, calibration, and quality control"}], "description": "Students learn design and administration choices that reduce error."}]}, {"id": "8de605be-63d1-466a-af11-b5e6df637e09", "type": "topic", "title": "Validity Evidence, Interpretation, and Test Use", "description": "This module treats validity as the central argument linking scores to interpretations, decisions, and consequences.", "children": [{"id": "80be1660-5a68-4cae-a9eb-b2995688e36c", "type": "subtopic", "title": "Validity argument", "children": [{"id": "a6973dec-09cb-42f8-ace0-da2a4cef34d0", "type": "concept", "title": "Content, response process, internal structure, relations to other variables, and consequences"}, {"id": "b1558d66-9d75-4bb7-b13a-5ce0283cd140", "type": "concept", "title": "Construct underrepresentation and construct-irrelevant variance"}, {"id": "9bed774e-7bbe-466f-ba17-accb98a31e09", "type": "concept", "title": "Validity for specific populations, purposes, and settings"}], "description": "Validity is about whether evidence supports the intended score interpretation and use."}, {"id": "fdea8957-b88e-4b16-bd45-b4e8e199baa1", "type": "subtopic", "title": "Criterion and construct evidence", "children": [{"id": "36b6abff-e3df-4c94-834b-8591dd7b634d", "type": "concept", "title": "Concurrent, predictive, convergent, and discriminant evidence"}, {"id": "cc86e173-6bb4-433b-90b2-156c91646d52", "type": "concept", "title": "Sensitivity, specificity, ROC curves, and utility"}, {"id": "8345304e-3ce9-4803-80fc-cc71c4946caa", "type": "concept", "title": "Incremental validity and decision usefulness"}], "description": "Students evaluate whether scores relate to meaningful outcomes and theory."}, {"id": "ad6867f6-50a6-48a9-bcf8-7704138fecde", "type": "subtopic", "title": "Consequences of testing", "children": [{"id": "adf2c353-5a9d-4960-9d2f-6f942e47d402", "type": "concept", "title": "Selection, diagnosis, eligibility, stigma, opportunity, and resource allocation"}, {"id": "bac58cc4-7998-4329-a05d-afc888edc844", "type": "concept", "title": "Adverse impact and fairness evidence"}, {"id": "c45241ce-3a13-4822-b8b5-6767ef88a777", "type": "concept", "title": "Misuse, overclaiming, and responsible caveats"}], "description": "A world-class assessment course considers what happens after a score is used."}]}, {"id": "58262899-3005-4098-a037-7884654867a7", "type": "topic", "title": "Test Construction, Item Analysis, Scaling, and Factor Analysis", "description": "Students learn how high-quality instruments are designed, refined, scaled, and structurally evaluated.", "children": [{"id": "8ea27456-07dc-4614-a85e-a173557111f2", "type": "subtopic", "title": "Test development process", "children": [{"id": "5d21cd1e-c884-494c-a782-a47b64eb5dda", "type": "concept", "title": "Construct map and test blueprint"}, {"id": "e1c2cb42-a659-4fba-89e6-f8f5c04d579d", "type": "concept", "title": "Item writing, review, piloting, and revision"}, {"id": "52d06034-e0c6-44e9-a1ed-85468aa1ddbc", "type": "concept", "title": "Administration format, scoring plan, and documentation"}], "description": "Students learn how instruments move from construct definition to usable measure."}, {"id": "b414f661-0e70-497b-8de3-5847c1697a9b", "type": "subtopic", "title": "Item analysis", "children": [{"id": "d9d97eb2-43fe-4a58-b8af-96b63bd8c6af", "type": "concept", "title": "Item difficulty, discrimination, endorsement rates, and distractor analysis"}, {"id": "836c5274-916f-4ad1-8cd7-5d6c7363ce52", "type": "concept", "title": "Item-total correlations and reliability if item deleted"}, {"id": "36b0410c-67c1-469e-90ea-7eca58cd5c8e", "type": "concept", "title": "Differential item functioning as an early fairness signal"}], "description": "The point is to identify items that perform well psychometrically and substantively."}, {"id": "8248e4a0-59bd-4657-a3fb-f4bad50b4460", "type": "subtopic", "title": "Factor analysis and scaling", "children": [{"id": "06ea19df-5040-4889-aa71-8c6ef6e2ccc3", "type": "concept", "title": "Exploratory and confirmatory factor analysis"}, {"id": "8b7bc697-5a87-4648-b706-9da486b6b30e", "type": "concept", "title": "Dimensionality, loadings, cross-loadings, and model fit"}, {"id": "6c946e6f-7139-4cbb-93ff-8c83b0548d52", "type": "concept", "title": "Scale scoring, short forms, and validity tradeoffs"}], "description": "Students learn how internal structure evidence is evaluated."}]}, {"id": "b217a185-ab0d-4f21-82e4-4fd882a33fd9", "type": "topic", "title": "Item Response Theory, Computerized Testing, and Modern Psychometrics", "description": "This topic introduces modern measurement models and adaptive testing as extensions beyond classical test theory.", "children": [{"id": "b95413b7-a203-4e77-aaab-249b841b3a85", "type": "subtopic", "title": "IRT concepts", "children": [{"id": "49b865b0-331c-4ba4-812a-804e21a9ea05", "type": "concept", "title": "Difficulty, discrimination, guessing, and information"}, {"id": "b05abedb-3cea-43a0-83ea-7494a984da89", "type": "concept", "title": "Item and test information functions"}, {"id": "d80f4b5e-324d-466d-948f-1ad44886fb8d", "type": "concept", "title": "Theta estimates and conditional precision"}], "description": "IRT models item and person parameters to understand measurement across trait levels."}, {"id": "19657c3c-451c-44a3-b688-8c17464b1710", "type": "subtopic", "title": "Adaptive and computerized testing", "children": [{"id": "c2b6059b-8d4b-4d0c-8d47-cf322ee11ea5", "type": "concept", "title": "Computerized adaptive testing"}, {"id": "cbc4347e-756c-4f2c-be89-fb5cb396de55", "type": "concept", "title": "Item banks and exposure control"}, {"id": "342c6a5a-180e-4d65-bb55-51e664afb921", "type": "concept", "title": "Remote testing, proctoring, and digital accessibility"}], "description": "Modern testing can tailor item delivery and scoring to examinee performance."}, {"id": "7d3b8754-e805-4eba-b9c5-433fff4fb82b", "type": "subtopic", "title": "Emerging measurement issues", "children": [{"id": "33703fab-b873-46d2-920f-f68cf190f48f", "type": "concept", "title": "Automated scoring and algorithmic assessment"}, {"id": "8f12f3b1-47e4-4622-b6da-297026bbd78f", "type": "concept", "title": "Digital phenotyping and passive data cautions"}, {"id": "b902cb5a-d3a3-4c7b-bb7c-d95284d3ed9d", "type": "concept", "title": "Transparency, bias audits, and model governance"}], "description": "Students consider new tools without losing psychometric discipline."}]}, {"id": "af338cb1-89f0-4e07-83c6-a1c2c9e98b16", "type": "topic", "title": "Test Selection, Administration, Scoring, Norming, and Quality Control", "description": "Students learn the practical workflow that protects standardization, accuracy, documentation, and interpretive integrity.", "children": [{"id": "7af7f6a3-7b33-47b6-bbdb-24e1ac3c1d76", "type": "subtopic", "title": "Test selection", "children": [{"id": "28592425-8795-4982-8062-0301fd07aa96", "type": "concept", "title": "Purpose, age range, language, norms, and qualification level"}, {"id": "dabf3122-3aa7-4712-b5b0-fc2a3beece1c", "type": "concept", "title": "Reliability, validity, fairness, and practical constraints"}, {"id": "645707c5-f4f2-47be-8799-d95c28ed3ee3", "type": "concept", "title": "Buros reviews, manuals, and professional guidelines"}], "description": "Students learn to choose tools by referral question, evidence, population, and setting."}, {"id": "8552e17a-149f-4236-969a-55f394830d04", "type": "subtopic", "title": "Administration and scoring", "children": [{"id": "0ae4cb22-19ce-4128-89df-86cbea3e63bb", "type": "concept", "title": "Standardized instructions, timing, rapport, and environment"}, {"id": "f7d3a60a-34a6-4242-9155-202984fbec95", "type": "concept", "title": "Raw-to-standard score conversion"}, {"id": "9ef27cb8-3bf8-4f14-a815-a147f4d15225", "type": "concept", "title": "Scoring checks, missing data, and protocol review"}], "description": "Standard procedures protect comparability and interpretive validity."}, {"id": "144a81a5-ced3-40de-8aef-1b9e152aef56", "type": "subtopic", "title": "Quality control", "children": [{"id": "21b523a9-3ef1-47c4-8bf5-456e95204830", "type": "concept", "title": "Test security and chain of custody"}, {"id": "daf4a75c-741b-4e6d-91ff-ace237911a15", "type": "concept", "title": "Record keeping and audit trails"}, {"id": "749d8b47-849d-4656-83c9-394fcebc175a", "type": "concept", "title": "Correction procedures, versioning, and supervision"}], "description": "Assessment data need traceable documentation and error prevention."}]}, {"id": "f831e80e-5272-477c-b5e4-e2438e6b97e4", "type": "topic", "title": "Intelligence, Cognitive, Achievement, and Learning Assessment", "description": "This section examines cognitive and achievement testing, including theories of intelligence and educational decision contexts.", "children": [{"id": "219794aa-14f0-4923-bdab-b934cb41254d", "type": "subtopic", "title": "Intelligence theories", "children": [{"id": "f7754948-be3d-437e-a0b4-00e125b4d89c", "type": "concept", "title": "g, CHC theory, processing speed, working memory, verbal comprehension, and visual-spatial reasoning"}, {"id": "d7d2588f-11da-415c-97ba-1122ccd9ce4a", "type": "concept", "title": "History and controversies of intelligence testing"}, {"id": "cb5472f8-991c-439f-b152-3155b42be54c", "type": "concept", "title": "Strengths, limits, and cultural interpretation"}], "description": "Students connect cognitive tests to theory instead of treating IQ as a single simple thing."}, {"id": "48f3f21a-1c3f-41af-9a87-e985b9ae9e79", "type": "subtopic", "title": "Major instruments", "children": [{"id": "cef86872-1f67-426b-aba9-382e0a6cb2d8", "type": "concept", "title": "Wechsler scales, Stanford-Binet, Woodcock-Johnson, and achievement batteries"}, {"id": "178c5f57-5069-4ffb-a7e4-06d1ab51420d", "type": "concept", "title": "Composite scores, index scores, and profile interpretation"}, {"id": "97592045-32bb-4d77-a57a-4b60cb28a8e4", "type": "concept", "title": "Practice effects and retesting"}], "description": "Students learn what common cognitive and achievement tests are designed to measure."}, {"id": "f2e7abad-6a94-467e-9288-53552f216c2b", "type": "subtopic", "title": "Learning and educational decisions", "children": [{"id": "e72ae05a-a9b6-449b-a32f-bb5846c6c249", "type": "concept", "title": "Learning disability models and eligibility cautions"}, {"id": "f73c877f-7779-42c8-b87a-d0d393f4105d", "type": "concept", "title": "Giftedness, twice-exceptionality, and accommodations"}, {"id": "78e00e22-3d35-48fc-89dd-1792efa20776", "type": "concept", "title": "Recommendations for instruction and support"}], "description": "Cognitive data can support education when integrated with achievement, history, and context."}]}, {"id": "3d87c148-fa4a-425b-b34e-6198c138233f", "type": "topic", "title": "Personality, Clinical, Behavioral, and Symptom Assessment", "description": "Students learn how inventories, interviews, rating scales, and behavioral methods support psychological formulation.", "children": [{"id": "cd94ac2a-a386-4da9-a6d0-135a4f690e57", "type": "subtopic", "title": "Personality inventories", "children": [{"id": "b4daf0ed-1480-4fe8-a406-670b41814715", "type": "concept", "title": "MMPI, PAI, MCMI, NEO/IPIP, and trait inventories"}, {"id": "75ab5074-640f-49ab-8aaa-b302afa12508", "type": "concept", "title": "Validity scales, response style, and profile interpretation"}, {"id": "1af26ad6-9bd6-40d8-885e-e35994582c91", "type": "concept", "title": "Norms, base rates, and clinical cutoffs"}], "description": "Students learn objective approaches to personality and psychopathology assessment."}, {"id": "73313f58-1435-4e11-8cc7-b7aa9efcc7d6", "type": "subtopic", "title": "Clinical and symptom measures", "children": [{"id": "de95a4f0-8162-4d43-86b1-1dc0b609958a", "type": "concept", "title": "Structured and semi-structured interviews"}, {"id": "6cac2047-58b9-4590-b4d1-ff182652fd8a", "type": "concept", "title": "Depression, anxiety, trauma, substance use, and risk measures"}, {"id": "f2ff20ff-356b-4bd9-966f-1897367bbcb4", "type": "concept", "title": "Screening versus diagnosis"}], "description": "Assessment supports diagnosis and treatment planning when used carefully."}, {"id": "c947fdf2-f600-4315-9e37-65cd904741ed", "type": "subtopic", "title": "Behavioral assessment", "children": [{"id": "b812cd36-8e8b-41b3-9ef5-235da0ea83f7", "type": "concept", "title": "Functional behavioral assessment"}, {"id": "f947411a-ad7c-40d5-ba84-56d91dc73a43", "type": "concept", "title": "Observation, ratings, logs, ecological momentary assessment"}, {"id": "6cb225bb-af91-442a-8db2-ce8a0a52cf15", "type": "concept", "title": "Antecedents, behaviors, consequences, and intervention targets"}], "description": "Behavior is measured in context, not only through self-report."}]}, {"id": "d418df46-ee5d-4d2d-94e1-c3e7385b6926", "type": "topic", "title": "Neuropsychological, Developmental, and Special Population Assessment", "description": "This topic introduces assessment of cognitive domains, lifespan needs, disability, and complex referral questions.", "children": [{"id": "5a0cffce-fdc6-4394-8202-f16bcfe9b5ef", "type": "subtopic", "title": "Neuropsychological domains", "children": [{"id": "331cdfd2-3ce8-4c5d-801f-dc02e755c852", "type": "concept", "title": "Attention, memory, language, executive function, visuospatial skill, motor function, and processing speed"}, {"id": "70164e4b-626c-41d2-9c9d-f6d9f4b44eb8", "type": "concept", "title": "Screening versus comprehensive evaluation"}, {"id": "ba623eb2-2598-4537-b644-29e1aa74288a", "type": "concept", "title": "Localization cautions and ecological validity"}], "description": "Students learn how tests map to broad cognitive and behavioral domains."}, {"id": "f3227ff9-ebcd-4a8b-b1da-b682ea69dfb2", "type": "subtopic", "title": "Developmental and lifespan assessment", "children": [{"id": "1336bd46-2a2a-410b-b93a-b0fdd05817f5", "type": "concept", "title": "Early childhood, school-age, adolescent, adult, and older adult assessment"}, {"id": "7d41f3e4-c293-4e43-ac73-9b39f42ed36e", "type": "concept", "title": "Developmental delay, ADHD, autism, dementia, and acquired injury"}, {"id": "9ebb6fbc-3a34-4695-9bb0-d4032f1b2b1e", "type": "concept", "title": "Informants, records, and collateral data"}], "description": "Assessment changes with age, developmental stage, and referral context."}, {"id": "1e5758d0-8780-44f4-ae83-c6759391e59a", "type": "subtopic", "title": "Special populations", "children": [{"id": "16311174-a156-4c6b-a668-756c929c6171", "type": "concept", "title": "Disability, sensory impairment, language differences, and medical factors"}, {"id": "16281a65-6df7-4da6-972a-f25303cc9d4c", "type": "concept", "title": "Trauma-informed and accessibility-aware assessment"}, {"id": "6aa39d93-5aaf-4ff6-9f27-3f2c67b99000", "type": "concept", "title": "When to refer to specialists"}], "description": "Students learn to adapt ethically without invalidating results."}]}, {"id": "1ce84ba6-1c79-4d12-8de5-7533ca6b04a9", "type": "topic", "title": "Fairness, Bias, Cultural Responsiveness, Accommodations, and Accessibility", "description": "Students learn to identify and reduce bias while supporting valid assessment for diverse examinees.", "children": [{"id": "6d8a4425-f3a4-43b2-8ee0-4e9455ab7bc4", "type": "subtopic", "title": "Fairness concepts", "children": [{"id": "d8c1458f-f0fb-4cbf-a613-4cb2262c6408", "type": "concept", "title": "Bias, adverse impact, differential prediction, and differential item functioning"}, {"id": "0acb1e49-ab28-48c6-8765-8d2badcf6999", "type": "concept", "title": "Measurement invariance and subgroup evidence"}, {"id": "fe0043fe-2394-4457-9b32-5c3d20d7bbde", "type": "concept", "title": "Interpretive equity and decision consequences"}], "description": "Fairness is a validity and ethics issue, not an optional add-on."}, {"id": "c169508a-9d3a-48fe-b41d-313ef5abf04e", "type": "subtopic", "title": "Cultural responsiveness", "children": [{"id": "377362a4-a5eb-4900-8951-d69d27795338", "type": "concept", "title": "Cultural formulation and contextual interviewing"}, {"id": "c664bfbf-933a-419f-88ea-9e1cbc54cddc", "type": "concept", "title": "Race, ethnicity, gender, sexuality, class, religion, disability, and migration"}, {"id": "e7304684-ec55-4334-aba1-67dd3a2d22a0", "type": "concept", "title": "Avoiding stereotyping and cultural blindness"}], "description": "Students learn to assess people in cultural, linguistic, and social context."}, {"id": "e8f4b471-ae0e-4811-b7ae-ef0819bc8188", "type": "subtopic", "title": "Accommodations and accessibility", "children": [{"id": "01892153-28bb-405e-996a-21b31d3f6fd1", "type": "concept", "title": "Standard versus nonstandard accommodations"}, {"id": "ec13b939-0a65-4cb4-a40b-6810e292d10e", "type": "concept", "title": "Language interpretation and translation limits"}, {"id": "cb2d4049-fb5e-4f78-ab51-e1d8acf17562", "type": "concept", "title": "Universal design, assistive technology, and documentation"}], "description": "Valid assessment often requires access-oriented planning."}]}, {"id": "dff42352-c744-4344-8b45-77dbc538c30d", "type": "topic", "title": "Ethical, Legal, Professional, and Security Standards", "description": "This module anchors assessment practice in professional standards, consent, competence, confidentiality, test security, and law.", "children": [{"id": "1090a4b9-c7dd-4f24-898e-a53f8fc8fec0", "type": "subtopic", "title": "Professional standards", "children": [{"id": "1e4d3825-e73a-496a-9e64-8f3e7ef2f45f", "type": "concept", "title": "Standards for Educational and Psychological Testing"}, {"id": "a222b7ec-6369-4b3c-9c6b-0ff348c2ed4f", "type": "concept", "title": "APA ethics, test-user competence, and scope of practice"}, {"id": "48c5bf04-8e7e-4766-911d-08d13bebce30", "type": "concept", "title": "International Test Commission guidance"}], "description": "Students learn the major rules that govern responsible assessment."}, {"id": "3eb50a26-7f72-45dd-8d74-f5ea0dd81787", "type": "subtopic", "title": "Legal and institutional issues", "children": [{"id": "81647c21-30ed-49ee-912b-2449a34dedbd", "type": "concept", "title": "Informed consent, privacy, FERPA/HIPAA basics, and mandated reporting contexts"}, {"id": "c31d03db-8c21-4916-bc60-3d648ac879f0", "type": "concept", "title": "ADA, accommodations, school eligibility, employment testing, and forensic cautions"}, {"id": "bd182387-6c94-45aa-affe-dbfa2a1429b4", "type": "concept", "title": "Documentation, subpoenas, and record release"}], "description": "Assessment decisions interact with law, policy, and rights."}, {"id": "d7481178-237e-4347-bf16-3c38ba313dfe", "type": "subtopic", "title": "Test security and misuse", "children": [{"id": "a16340cc-dae5-492a-b7f7-eb1cec58acef", "type": "concept", "title": "Copyright, item exposure, and secure materials"}, {"id": "3252a863-5ee1-4b9e-afbc-062eb5375e3a", "type": "concept", "title": "AI summaries, online test leaks, and unqualified use"}, {"id": "0f59a229-a425-40da-add3-58a09264a0e6", "type": "concept", "title": "Limits, disclaimers, and correction of misinterpretation"}], "description": "Protecting instruments protects examinees and validity."}]}, {"id": "c580b61e-5565-4590-aaed-d2feaf72af2a", "type": "topic", "title": "Integrative Assessment, Case Formulation, and Decision-Making", "description": "Students synthesize data sources into defensible interpretations, recommendations, and referral decisions.", "children": [{"id": "70a51aa8-fd84-4073-9a3c-5f6722342912", "type": "subtopic", "title": "Data integration", "children": [{"id": "5fce4b1d-794d-4950-ab4d-41988d52f76c", "type": "concept", "title": "Referral question, history, observation, interview, records, and test data"}, {"id": "a929f9ea-f6f3-4fca-8e10-70b5e8b36490", "type": "concept", "title": "Converging and conflicting evidence"}, {"id": "0294efad-4f02-4d10-96f6-4e2d088c9a34", "type": "concept", "title": "Strengths, limitations, and alternative explanations"}], "description": "Students learn to synthesize rather than list test results."}, {"id": "882c0958-af72-4166-953b-bc95d3b63631", "type": "subtopic", "title": "Case formulation", "children": [{"id": "63eef230-b7e0-414c-936a-1d755ad68e1f", "type": "concept", "title": "Biopsychosocial and ecological formulation"}, {"id": "225ead33-5be0-4c24-8c8b-8d0896a1aecb", "type": "concept", "title": "Diagnostic, educational, occupational, and treatment implications"}, {"id": "4f313315-669e-435b-b16b-20c0b98300bd", "type": "concept", "title": "Risk, protective factors, and contextual constraints"}], "description": "Assessment should explain patterns and guide next steps."}, {"id": "8600a196-578d-47f4-93ef-b653a9a770a7", "type": "subtopic", "title": "Decision-making", "children": [{"id": "41583d59-3018-4c46-9046-b214978e9714", "type": "concept", "title": "Cut scores, base rates, and classification risk"}, {"id": "dcec43b6-bd2b-4817-a700-dc8a60cc0635", "type": "concept", "title": "Eligibility, referral, treatment planning, and monitoring"}, {"id": "a5b294c7-4992-4c7b-9ce0-86cf3e696bbd", "type": "concept", "title": "Shared decision-making and ethical uncertainty"}], "description": "Students learn to make recommendations proportional to evidence."}]}, {"id": "8866cecc-7f69-448b-a479-07bd6ad045ce", "type": "topic", "title": "Report Writing, Feedback, Communication, and Collaborative Consultation", "description": "This topic develops the communication skills needed to make assessment useful, clear, respectful, and actionable.", "children": [{"id": "b366038c-7dc0-4936-8af4-37dd056e6573", "type": "subtopic", "title": "Report structure", "children": [{"id": "5ed48834-fd10-435c-b852-10322ddc4dde", "type": "concept", "title": "Referral question, methods, behavior observations, results, interpretation, summary, and recommendations"}, {"id": "618bbe18-934e-4cf4-8137-784222e0380c", "type": "concept", "title": "Readable tables, score explanations, and confidence intervals"}, {"id": "6a1ed58b-feb7-4a3e-8d60-755a331a1811", "type": "concept", "title": "Clear caveats and limitations"}], "description": "Reports translate complex data into useful, defensible communication."}, {"id": "cbeed1a5-39b2-4e50-bc0f-9fe0e6babb92", "type": "subtopic", "title": "Feedback", "children": [{"id": "192bbc44-f4e7-45c3-ac9a-b0fc54f83883", "type": "concept", "title": "Feedback sessions with clients, families, teams, or referring providers"}, {"id": "07b70914-d5fe-458e-afdf-af734eefa033", "type": "concept", "title": "Plain language and strengths-based framing"}, {"id": "a4133ffd-4d86-40a2-b116-5c688083fa7c", "type": "concept", "title": "Managing distress, disagreement, and uncertainty"}], "description": "Assessment feedback should be accurate, compassionate, and actionable."}, {"id": "ab81f7cb-bb3a-4b50-be4b-81e3f037c21c", "type": "subtopic", "title": "Consultation and collaboration", "children": [{"id": "e6f648c6-35bc-4c70-a9af-33358103bcc0", "type": "concept", "title": "Schools, clinics, workplaces, and interprofessional teams"}, {"id": "c47e6a71-2677-464a-832b-4a83c51def15", "type": "concept", "title": "Recommendations that fit resources and context"}, {"id": "d83fb2bc-5cfd-491d-a8c9-9cecec04ed86", "type": "concept", "title": "Follow-up, progress monitoring, and referral pathways"}], "description": "Assessment often works through teams and systems."}]}, {"id": "e211c8d1-ebc7-46c4-8db7-bd5027112b38", "type": "topic", "title": "Assessment Critique and Test Development Capstone", "description": "Students demonstrate mastery by evaluating an existing instrument or developing a defensible mini-assessment plan.", "children": [{"id": "941b8f06-fd79-4db3-ad9f-b245bfb6fe0c", "type": "subtopic", "title": "Test critique", "children": [{"id": "601fa65a-2b57-41c0-9eda-2844d1e83c94", "type": "concept", "title": "Construct, intended use, norms, reliability, validity, fairness, and usability"}, {"id": "542a0dff-0716-4a66-bd42-0bf4431ffb1d", "type": "concept", "title": "Manual review and independent test reviews"}, {"id": "130799ea-442c-471a-a34d-cdfac7cd51c1", "type": "concept", "title": "Appropriate and inappropriate use cases"}], "description": "Students demonstrate they can evaluate a real instrument before using it."}, {"id": "3f07bd70-37ad-4047-abb1-6509074ad055", "type": "subtopic", "title": "Mini-measure development", "children": [{"id": "6c939c4e-f581-4bf4-8260-edd3675a4696", "type": "concept", "title": "Construct definition and blueprint"}, {"id": "4975f19a-d790-48a1-8025-f213b3b97803", "type": "concept", "title": "Item writing, pilot plan, reliability/validity plan"}, {"id": "2f0ff3a7-f708-4c42-8c2b-60c2afa93988", "type": "concept", "title": "Fairness, accessibility, and documentation"}], "description": "Students practice building a small defensible measure."}, {"id": "ca4f5f2b-e625-4a56-98a5-1c88761731c5", "type": "subtopic", "title": "Professional product", "children": [{"id": "eec657e8-0a26-4816-9632-a1a3cd2e87c1", "type": "concept", "title": "Test review memo, assessment battery plan, or prototype scale"}, {"id": "dad51c27-dd7c-4585-b3b2-603bd2eb6c3b", "type": "concept", "title": "Ethics and limitations section"}, {"id": "f8c617b2-137a-4710-8345-1c78e449fdfd", "type": "concept", "title": "Brief presentation with recommendations"}], "description": "The capstone turns assessment knowledge into a polished deliverable."}]}], "dbBacked": true}$psytjson$::jsonb,
